from fastapi import BackgroundTasks, FastAPI, status

events: list[str] = []
app = FastAPI()

def record_notification(email: str, message: str) -> None:
    events.append(f"{email}:{message}")

@app.post("/notifications/{email}", status_code=status.HTTP_202_ACCEPTED)
async def create_notification(email: str, background_tasks: BackgroundTasks) -> dict[str, bool]:
    background_tasks.add_task(record_notification, email, message="welcome")
    return {"accepted": True}

